def variants(a):
    e=html.escape(a,quote=False); yield a; yield e; yield e.replace('"','&quot;'); yield a.replace("'","&#x27;"); yield e.replace("'","&#x27;"); yield e.replace("'","&#x27;").replace('"','&quot;'); yield a.replace("'","’")
miss=[]
for f in sorted(D.glob('*.html')):
    s=o=f.read_text()
    for a,b in R['*']+R.get(f.name,[]):
        hit=False
        for A,B in zip(variants(a),variants(b)):
            if A in s: s=s.replace(A,B); hit=True; break
        if not hit and f.name in R and (a,b) in R[f.name] and not any(B in s for B in variants(b)): miss.append((f.name,a[:50]))
    if f.name=='index.html':
        s=s.replace('Russia, Ukraine &amp; Georgia','Eurasia').replace('russia, ukraine &amp; georgia','eurasia').replace('Russia, Ukraine & Georgia','Eurasia')
    if f.name=='index.html': s=re.sub(r'(<details class="rg rx-g[^"]*"[^>]*?) open>',r'\1>',s)
    if s!=o: f.write_text(s)
print('MISSES',miss)
